import {createCafeAmbience} from './cafe-ambience.js';
import {createCafeChatUI} from './cafe-chat-ui.js';
import {createCafeScene} from './cafe-scene.js';
import {createCafeMenu} from './cafe-menu.js';
import {cafeMenu,cafeSeats} from './cafe-catalog.js';
import {atCafeCounter,CAFE_COUNTER} from './cafe-service-state.js';
import {newId} from './cloud.js';
export function createCafeUI({cloud,toast,beforeOpen,onClose,onMusic}){
 const ambience=createCafeAmbience();
 const link=document.createElement('link');link.rel='stylesheet';link.href='./cafe.css';document.head.append(link);
 const entry=document.createElement('button');entry.className='pill';entry.textContent='海边咖啡馆';entry.id='visit-cafe';(document.querySelector('#world-menu .menu-items')||document.querySelector('nav')).append(entry);
 const shell=document.createElement('section');shell.id='cafe';shell.hidden=true;shell.setAttribute('aria-label','海边咖啡馆');shell.innerHTML='<div class="cafe-stage"></div><button class="cafe-music" data-cafe="music" aria-label="打开音乐">♫</button><header class="cafe-top"><button data-cafe="leave">‹ 回家</button><div><strong>海风来信</strong><small class="cafe-time"></small></div><span class="cafe-count"></span></header><div class="cafe-host-bubble" hidden>想喝点什么？也有今天的甜品。</div><div class="cafe-actions" hidden></div><div class="cafe-note" role="status"></div><a class="cafe-credits" href="./assets/coast/CREDITS.txt" target="_blank" rel="noopener">素材署名</a>';document.body.append(shell);
 const actions=shell.querySelector('.cafe-actions'),note=shell.querySelector('.cafe-note'),bubble=shell.querySelector('.cafe-host-bubble');let scene=null,active=false,opening=false,busy=false,syncing=false,timer=null,epoch=0,data=null,pose={x:0,z:4.1,yaw:Math.PI},entered=false,greeted=false,routeResolve=null,noteTimer=null,issued=0,accepted=0,pendingOrder=null,bubbleUntil=0,actionKey='',dessertBrowsing=false,eating=false;
 const chat=createCafeChatUI(shell,cloud),menu=createCafeMenu(shell,placeOrder,()=>{bubbleUntil=0;bubble.hidden=true},visible=>scene?.menuView(visible));
 const mine=()=>data?.guests.find(g=>g.id===data.self),clock=()=>Date.now()+(data?data.sky.time-data.receivedAt:0),handover=()=>mine()?.handoff?.endsAt>clock();
 const message=text=>{note.textContent=text;clearTimeout(noteTimer);noteTimer=setTimeout(()=>{note.textContent=''},6000)};
 function say(text){bubble.textContent=text;bubbleUntil=Date.now()+6500}
 function ownActions(){actions.hidden=true;const g=mine();if(g?.order&&g.order.readyAt<=clock()&&actionKey!==g.order.command){actionKey=g.order.command;say('做好了，点吧台上的托盘就可以拿走。')} }
 function paint(value,sequence=++issued){if(sequence<accepted)return;accepted=sequence;value.receivedAt=Date.now();data=value;scene?.update(value);shell.classList.toggle('cafe-night',value.sky.night);const g=mine();chat.seat(cafeSeats.find(s=>s.id===g?.seat)?.zone==='bar');shell.querySelector('.cafe-time').textContent=new Date(value.sky.time).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'})+` · ${value.sky.weather==='rain'?'小雨':value.sky.night?'夜晚':'晴天'} · ${value.sky.temperature}°`;shell.querySelector('.cafe-count').textContent=`${value.guests.length} 位访客`;ownActions()}
 async function action(body){if(busy||!active)return null;busy=true;const token=epoch,sequence=++issued;try{const r=await cloud.cafe(body);if(token!==epoch)return null;paint(r,sequence);return r}catch(e){if(token===epoch)message(e.message||'连接中断，请稍后重试');return null}finally{if(token===epoch)busy=false}}
 async function sync(){if(!active||busy||syncing||document.hidden)return;syncing=true;const token=epoch,sequence=++issued;try{const r=await cloud.cafe({action:'sync',...pose});if(token===epoch)paint(r,sequence)}catch(e){if(token===epoch){if(e.status===409){try{const r=await cloud.cafe({action:'join'});if(token===epoch){paint(r);message('已重新回到咖啡馆')}}catch{message('正在重新连接…')}}else message('正在重新连接…')}}finally{syncing=false}}
 async function open(){if(active||opening)return;if(!cloud){toast('登录后就可以和大家一起去咖啡馆');return}ambience.unlock();opening=true;window.planetArrival?.start(false,'正在前往海边咖啡馆');shell.inert=true;try{if(!await cloud.flush())return;const r=await cloud.cafe({action:'join',fresh:true});beforeOpen();document.querySelector('#world-menu')?.close();active=true;epoch++;document.body.classList.add('in-cafe');shell.hidden=false;scene=createCafeScene(shell.querySelector('.cafe-stage'),{onEnvironment:inside=>ambience.room(inside),onPick:pick,onMove:v=>{pose=v;if(!active||!entered||dessertBrowsing)return;const near=atCafeCounter(v);if(!near)greeted=false;if(near&&!v.moving&&!greeted&&!mine()?.order&&!mine()?.held){greeted=true;say('想喝点什么？也有今天的甜品。');menu.show();actions.hidden=true}},onHostPoint:p=>{bubble.hidden=Date.now()>bubbleUntil||!p.visible;bubble.style.left=Math.max(125,Math.min(shell.clientWidth-125,p.x))+'px';bubble.style.top=Math.max(90,p.y-15)+'px'},onError:message});paint(r);scene.focus('island');timer=setInterval(sync,750);await scene.ready;if(active)ambience.play();message('点咖啡馆进店，拖动看看海岛')}catch(e){toast(e.message||'咖啡馆暂时没能打开');await close()}finally{opening=false;shell.inert=false;await window.planetArrival?.finish()}}
 async function close(){ambience.stop();chat.reset();const had=active;routeResolve?.(false);routeResolve=null;active=false;epoch++;clearInterval(timer);clearTimeout(noteTimer);scene?.dispose();scene=null;shell.hidden=true;actions.hidden=true;menu.hide();menu.clear();pendingOrder=null;entered=greeted=false;bubbleUntil=0;busy=false;actionKey='',dessertBrowsing=false,eating=false;document.body.classList.remove('in-cafe');sessionStorage.removeItem('echoo-cafe-open');if(had){try{await cloud.cafe({action:'leave'})}catch{}onClose?.();await cloud.refresh()}}
 async function walk(x,z){if(handover()){message('先接好托盘再走吧');return false}routeResolve?.(false);routeResolve=null;scene.cancelRoute();if(mine()?.seat&&!await action({action:'stand'}))return false;const token=epoch;return new Promise(resolve=>{routeResolve=resolve;if(!scene.routeTo(x,z,()=>{routeResolve=null;resolve(token===epoch&&active)})){routeResolve=null;resolve(false)}})}
 async function enter(){menu.hide();entered=true;scene.focus('inside');await walk(0,2.9)}
 async function counter(item,pickup=false){dessertBrowsing=false;entered=true;menu.hide();scene.focus('bar');if(!await walk(CAFE_COUNTER.x,CAFE_COUNTER.z))return false;scene.face(Math.PI);pose.yaw=Math.PI;await action({action:'sync',...pose});if(!active)return false;greeted=true;if(!pickup&&!mine()?.order&&!mine()?.held){say('想喝点什么？也有今天的甜品。');menu.show(item);actions.hidden=true}return true}
 async function exitCafe(){menu.hide();if(await walk(0,5.6)){entered=false;greeted=false;scene.focus('exterior')}}
 async function desserts(){dessertBrowsing=true;entered=true;menu.hide();greeted=true;if(await walk(2.9,-1.45)){scene.face(Math.PI);scene.focus('desserts');message('点选柜里的甜品')}}
 async function pickup(command){if(!mine()?.order||mine().order.command!==command){message('这是其他客人的托盘');return}if(await counter(null,true)){const r=await action({action:'pickup',command});if(r){if(r.takeaway){message('已打包，放进你家冰箱了');void cloud.refresh()}else message('点喜欢的座位坐下');ownActions()}}}
 async function eat(item){if(mine()?.dining||eating||!mine()?.seat||!mine()?.held?.items.includes(item))return;eating=true;const token=epoch;try{await scene.sip(item);if(token===epoch&&active)await action({action:'eat',item})}finally{eating=false}}
 async function talk(){if(cafeSeats.find(s=>s.id===mine()?.seat)?.zone==='bar'){chat.open();return}const seat=cafeSeats.find(s=>s.zone==='bar'&&!data.guests.some(g=>g.seat===s.id));if(!seat){message('吧台座位暂时满了，稍后再来聊聊');return}dessertBrowsing=true;entered=true;greeted=true;scene.focus('bar');if(await walk(seat.approachX,seat.approachZ)){const r=await action({action:'seat',seat:seat.id});if(r){scene.lookAt(seat.x,seat.z);chat.open()}}dessertBrowsing=false}
 async function pick(p,point){if(busy||handover())return;if(p.type!=='item')dessertBrowsing=false;menu.hide();bubbleUntil=0;actions.hidden=true;if(p.type==='host'){await talk();return}if(p.type==='enter'){await enter();return}if(p.type==='exit'){await exitCafe();return}if(p.type==='pickup'){await pickup(p.value);return}if(p.type==='eat'){await eat(p.value);return}if(p.type==='ground'){if(scene.state().frameMode==='desserts')scene.focus('inside');await walk(point.x,point.z);return}if(p.type==='seat'){entered=true;const s=cafeSeats.find(s=>s.id===p.value);if(await walk(s.approachX??s.x,s.approachZ??s.z+.58)){const seated=await action({action:'seat',seat:s.id});if(seated)scene.lookAt(s.x,s.z)}return}if(p.type==='drinks'){await counter();return}if(p.type==='item'){if(scene.state().frameMode!=='desserts')await desserts();else await counter(p.value)}}
 async function placeOrder(items,mode){if(busy)return;if(!atCafeCounter(pose)){message('先到吧台，再把菜单交给主理熊');return}if(!pendingOrder||JSON.stringify(pendingOrder.items)!==JSON.stringify(items)||pendingOrder.mode!==mode)pendingOrder={action:'order',items,mode,command:newId()};menu.busy(true);await action({action:'sync',...pose});const r=await action(pendingOrder);menu.busy(false);if(r){pendingOrder=null;menu.hide();menu.clear();ownActions();say('好呀，我来准备。做好了叫你！')}}
 shell.addEventListener('click',async e=>{if(e.target.closest('[data-cafe="music"]'))onMusic?.();if(e.target.closest('[data-cafe="leave"]'))await close()});
 entry.onclick=open;document.addEventListener('visibilitychange',()=>{if(!document.hidden)void sync()});window.addEventListener('pagehide',()=>{if(active)fetch('/api/cafe',{method:'POST',keepalive:true,headers:{'Content-Type':'application/json','X-CSRF-Token':cloud.session.csrf,'X-Planet-Space':String(cloud.session.space)},body:JSON.stringify({action:'leave'})}).catch(()=>{})});
 sessionStorage.removeItem('echoo-cafe-open');
 return {open,close,photoVisual:{photo(){},photoPose(p){return p==='current'},photoState(){return {room:scene?.state().inside,canPose:false}},capture(){return scene.capture()}},get active(){return active},state:()=>({active,room:data?.room,guests:data?.guests,scene:scene?.state()})};
}
